import React, { useCallback, useEffect, useMemo, useState } from "react";
import { Link, useParams } from "react-router-dom";
import api, { isCanceled } from "../services/api.ts";
import { useClub } from "../hooks/useClub.tsx";
import { useRefresh } from "../hooks/useRefresh.tsx";
import OverallSummaryCard, { ClubOverallRow, PlayoffAchievementDto } from "../components/OverallSummaryCard.tsx";
import { TeamStatsSection } from "../components/TeamStatsSection.tsx";
import { PlayerStatsTable } from "../components/PlayerStatsTable.tsx";
import { GoalLinkingSection } from "../components/GoalLinkingSection.tsx";
import { MatchEaPostGameStats } from "../components/MatchEaPostGameStats.tsx";
import { ClubStats, PlayerStats } from "../types/stats.ts";
import { MatchEventAggregatesResponseDto } from "../types/matchEventAggregates.ts";
import { crestUrl, API_ENDPOINTS } from "../config/urls.ts";
import { Crest, ResultPill } from "../components/ui.tsx";

// ======================
// Tipos (espelham /api/Matches/{matchId}/statistics)
// ======================
interface PlayerRow {
  playerId: number;
  playerName: string;
  clubId: number;

  matchesPlayed: number;
  totalGoals: number;
  totalAssists: number;
  totalShots: number;
  totalPassesMade: number;
  totalPassAttempts: number;
  totalTacklesMade: number;
  totalTackleAttempts: number;

  totalWins: number;
  totalLosses: number;
  totalDraws: number;
  totalCleanSheets: number;
  totalRedCards: number;
  totalSaves: number;
  totalMom: number;

  avgRating: number;

  passAccuracyPercent: number;
  tackleSuccessPercent: number;
  goalAccuracyPercent: number;
  winPercent: number;
}

interface ClubRow extends ClubStats {
  clubCrestAssetId?: string | null;
}

interface OverallRow {
  totalMatches: number;
  totalPlayers: number;
  totalGoals: number;
  totalAssists: number;
  totalShots: number;
  totalPassesMade: number;
  totalPassAttempts: number;
  totalTacklesMade: number;
  totalTackleAttempts: number;
  totalRating: number;
  totalWins: number;
  totalLosses: number;
  totalDraws: number;
  totalCleanSheets: number;
  totalRedCards: number;
  totalSaves: number;
  totalMom: number;

  avgGoals: number;
  avgAssists: number;
  avgShots: number;
  avgPassesMade: number;
  avgPassAttempts: number;
  avgTacklesMade: number;
  avgTackleAttempts: number;
  avgRating: number;
  avgRedCards: number;
  avgSaves: number;
  avgMom: number;

  winPercent: number;
  lossPercent: number;
  drawPercent: number;
  cleanSheetsPercent: number;
  momPercent: number;
  passAccuracyPercent: number;
  tackleSuccessPercent: number;
  goalAccuracyPercent: number;
}

interface FullMatchStatisticsDto {
  overall: OverallRow;
  players: PlayerRow[];
  clubs: ClubRow[];
}

// ======================
// Helpers
// ======================
function fmt(value: number | undefined | null) {
  if (value === undefined || value === null) return "–";
  return Number.isInteger(value) ? String(value) : (Math.round((value as number) * 100) / 100).toFixed(2);
}

const comparisonStats: Array<{
  label: string;
  key: keyof (ClubRow & PlayerRow);
}> = [
  { label: "Gols", key: "totalGoals" },
  { label: "Assistências", key: "totalAssists" },
  { label: "Chutes", key: "totalShots" },
  { label: "Precisão de Chutes (%)", key: "goalAccuracyPercent" },
  { label: "Passes Certos", key: "totalPassesMade" },
  { label: "Passes Tentados", key: "totalPassAttempts" },
  { label: "Precisão de Passe (%)", key: "passAccuracyPercent" },
  { label: "Desarmes Certos", key: "totalTacklesMade" },
  { label: "Desarmes Tentados", key: "totalTackleAttempts" },
  { label: "Precisão de Desarmes (%)", key: "tackleSuccessPercent" },
  { label: "Nota Média", key: "avgRating" },
];

const Badge: React.FC<{ className?: string; children: React.ReactNode; title?: string }> = ({
  className = "",
  children,
  title,
}) => (
  <span title={title} className={`text-xs px-2 py-0.5 rounded-full border ${className}`}>
    {children}
  </span>
);

const Skeleton: React.FC<{ className?: string }> = ({ className = "h-5 w-full" }) => (
  <div className={`animate-pulse rounded bg-surface-sunken ${className}`} />
);

const Button: React.FC<React.ButtonHTMLAttributes<HTMLButtonElement>> = ({ className = "", ...props }) => (
  <button
    {...props}
    className={`inline-flex items-center gap-2 rounded-lg border px-3 py-1.5 text-sm shadow-sm hover:bg-surface-raised disabled:opacity-60 ${className}`}
  />
);

// ======================
export default function MatchDetails() {
  const { matchId } = useParams();
  const { club, selectedClubIds } = useClub();

  const [stats, setStats] = useState<FullMatchStatisticsDto | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // caches para overall/playoffs
  const [overallCache, setOverallCache] = useState<Map<number, ClubOverallRow>>(new Map());
  const [playoffsCache, setPlayoffsCache] = useState<Map<number, PlayoffAchievementDto[]>>(new Map());
  // marca clubes já buscados com sucesso (evita re-fetch)
  const [fetchedOverall, setFetchedOverall] = useState<Set<number>>(new Set());
  const [overallBusy, setOverallBusy] = useState(false);
  const [overallErr, setOverallErr] = useState<string | null>(null);

  const [sortKey, setSortKey] = useState<keyof PlayerStats>("totalGoals");
  const [sortOrder, setSortOrder] = useState<"asc" | "desc">("desc");
  const [showOverallPanel, setShowOverallPanel] = useState<boolean>(false);

  // event-aggregates
  const [eventAggregates, setEventAggregates] = useState<MatchEventAggregatesResponseDto | null>(null);
  const [eventAggregatesLoading, setEventAggregatesLoading] = useState(false);
  const [eventAggregatesError, setEventAggregatesError] = useState<string | null>(null);

  // ====== Buscar estatísticas da partida ======
  const [reloadKey, setReloadKey] = useState(0);
  const reloadStats = useCallback(() => setReloadKey((k) => k + 1), []);
  // "Atualizar"/modo ao vivo do cabeçalho
  const { refreshKey } = useRefresh();

  useEffect(() => {
    if (!matchId) return;
    const controller = new AbortController();
    const { signal } = controller;
    (async () => {
      try {
        setLoading(true);
        setError(null);
        const { data } = await api.get<FullMatchStatisticsDto>(API_ENDPOINTS.MATCH_STATISTICS(matchId), { signal });
        if (signal.aborted) return;
        setStats(data);
      } catch (err: any) {
        if (signal.aborted || isCanceled(err)) return;
        setError(err?.message ?? "Erro ao buscar estatísticas");
      } finally {
        if (!signal.aborted) setLoading(false);
      }
    })();
    return () => controller.abort();
  }, [matchId, reloadKey, refreshKey]);

  // ====== Buscar event-aggregates ======
  useEffect(() => {
    if (!matchId) return;
    const controller = new AbortController();
    const { signal } = controller;
    (async () => {
      try {
        setEventAggregatesLoading(true);
        setEventAggregatesError(null);
        const { data } = await api.get<MatchEventAggregatesResponseDto>(
          API_ENDPOINTS.MATCH_EVENT_AGGREGATES(matchId),
          { signal }
        );
        if (signal.aborted) return;
        setEventAggregates(data ?? null);
      } catch (e) {
        if (signal.aborted || isCanceled(e)) return;
        setEventAggregatesError("Não foi possível carregar os dados de pós-jogo.");
      } finally {
        if (!signal.aborted) setEventAggregatesLoading(false);
      }
    })();
    return () => controller.abort();
  }, [matchId, reloadKey, refreshKey]);

  const players = stats?.players ?? [];
  const clubs = stats?.clubs ?? [];

  // >>> DEDUZIR O CLUB SELECIONADO DENTRO DESTE JOGO <<<
  const selectedClubId = useMemo<number | null>(() => {
    if (!stats?.clubs?.length) return club?.clubId ?? null;
    for (const id of selectedClubIds) {
      if (stats.clubs.some((c) => c.clubId === id)) return id;
    }
    if (club?.clubId && stats.clubs.some((c) => c.clubId === club.clubId)) return club.clubId;
    return stats.clubs[0]?.clubId ?? null;
  }, [stats?.clubs, selectedClubIds, club?.clubId]);

  // Ordena clubes mantendo o selecionado à esquerda
  const orderedClubs = useMemo(() => {
    if (!selectedClubId || clubs.length < 2) return clubs;
    const idx = clubs.findIndex((c) => c.clubId === selectedClubId);
    if (idx <= 0) return clubs;
    const clone = [...clubs];
    const [sel] = clone.splice(idx, 1);
    clone.unshift(sel);
    return clone;
  }, [clubs, selectedClubId]);

  const haveTwoClubs = orderedClubs.length >= 2;

  // Transform clubs to include totalGoalsConceded
  const clubsWithGoalsConceded = useMemo(() => {
    if (!haveTwoClubs) return orderedClubs;
    return orderedClubs.map((club, index) => {
      // goals conceded by one = goals scored by the other
      const opponentIndex = index === 0 ? 1 : 0;
      const goalsConceeded = orderedClubs[opponentIndex]?.totalGoals || 0;
      return {
        ...club,
        totalGoalsConceded: goalsConceeded,
      };
    });
  }, [orderedClubs, haveTwoClubs]);

  // ====== Reset de marcações se trocar partida ou par de clubes ======
  useEffect(() => {
    setFetchedOverall(new Set());
  }, [matchId, orderedClubs.map((c) => c.clubId).join(",")]);

  // ====== Fetch-once de Overalls/Playoffs (somente ao abrir o painel) ======
  const fetchOverallIfNeeded = useCallback(async (signal?: AbortSignal) => {
    if (!showOverallPanel) {
      setOverallBusy(false);
      return;
    }

    const targets = orderedClubs
      .slice(0, 2)
      .filter(Boolean)
      .filter((c) => !fetchedOverall.has(c.clubId));

    if (targets.length === 0) {
      setOverallBusy(false);
      return;
    }

    try {
      setOverallBusy(true);
      setOverallErr(null);

      const results = await Promise.all(
        targets.map(async (c) => {
          // Fetch both endpoints in parallel for each club
          const [overallRes, playoffsRes] = await Promise.all([
            api.get<ClubOverallRow>(`/api/Clubs/${c.clubId}/matches/${matchId}/overall`, { signal }),
            api.get<{ clubId: number; achievements: PlayoffAchievementDto[] }[]>(API_ENDPOINTS.CLUB_PLAYOFFS(c.clubId), { signal }),
          ]);

          const overall = overallRes.data ?? null;
          const playoffsBlock = playoffsRes.data?.find((x) => x.clubId === c.clubId) ?? playoffsRes.data?.[0];
          const playoffs = playoffsBlock?.achievements ?? [];

          return { clubId: c.clubId, overall, playoffs };
        })
      );

      if (signal?.aborted) return;

      setOverallCache((prev) => {
        const next = new Map(prev);
        for (const r of results) {
          if (r.overall) next.set(r.clubId, r.overall);
        }
        return next;
      });

      setPlayoffsCache((prev) => {
        const next = new Map(prev);
        for (const r of results) {
          next.set(r.clubId, r.playoffs);
        }
        return next;
      });

      setFetchedOverall((prev) => {
        const next = new Set(prev);
        for (const t of targets) next.add(t.clubId);
        return next;
      });
    } catch (e: any) {
      if (signal?.aborted || isCanceled(e)) return;
      setOverallErr(e?.message ?? "Erro ao buscar histórico do clube.");
    } finally {
      if (!signal?.aborted) setOverallBusy(false);
    }
  }, [showOverallPanel, orderedClubs, fetchedOverall, matchId]);

  useEffect(() => {
    const controller = new AbortController();
    fetchOverallIfNeeded(controller.signal);
    return () => controller.abort();
  }, [fetchOverallIfNeeded]);

  // Auxiliares do placar
  const haveScore = haveTwoClubs;
  const goalsA = haveScore ? orderedClubs[0].totalGoals : undefined;
  const goalsB = haveScore ? orderedClubs[1].totalGoals : undefined;
  const scoreLabel = haveScore ? `${goalsA} x ${goalsB}` : null;
  const leftWon = haveScore && (goalsA ?? 0) > (goalsB ?? 0);
  const rightWon = haveScore && (goalsB ?? 0) > (goalsA ?? 0);

  const leftIsSelected = !!selectedClubId && orderedClubs[0]?.clubId === selectedClubId;
  const rightIsSelected = !!selectedClubId && orderedClubs[1]?.clubId === selectedClubId;

  const selectedWon = (leftIsSelected && leftWon) || (rightIsSelected && rightWon);
  const selectedLost = (leftIsSelected && rightWon) || (rightIsSelected && leftWon);
  const heroBg = selectedWon ? "bg-positive-soft/30" : selectedLost ? "bg-negative-soft/30" : "";
  const heroBorderClass = selectedWon
    ? "border-l-4 border-l-positive"
    : selectedLost
    ? "border-l-4 border-l-negative"
    : "border-l-4 border-l-border-strong";

  // Identificar goleiro por clube
  const gkByClub = useMemo(() => {
    const map = new Map<number, PlayerRow | undefined>();
    for (const clubRow of clubs) {
      const pClub = players.filter((p) => p.clubId === clubRow.clubId && (p.totalSaves ?? 0) > 0);
      if (pClub.length === 0) {
        map.set(clubRow.clubId, undefined);
      } else {
        pClub.sort((a, b) => {
          const sDiff = (b.totalSaves ?? 0) - (a.totalSaves ?? 0);
          if (sDiff !== 0) return sDiff;
          const rDiff = (b.avgRating ?? 0) - (a.avgRating ?? 0);
          if (rDiff !== 0) return rDiff;
          return a.playerId - b.playerId;
        });
        map.set(clubRow.clubId, pClub[0]);
      }
    }
    return map;
  }, [players, clubs]);

  const cellHeat = (va?: number, vb?: number) => {
    const a = Number(va ?? 0);
    const b = Number(vb ?? 0);
    if (a === b) return { a: "", b: "" };
    return a > b
      ? { a: "bg-positive-soft/60 text-positive-fg font-semibold", b: "bg-negative-soft/50 text-negative-fg" }
      : { a: "bg-negative-soft/50 text-negative-fg", b: "bg-positive-soft/60 text-positive-fg font-semibold" };
  };

  const mom = (stats?.players ?? []).find((p) => (p.totalMom ?? 0) > 0);

  if (loading) {
    return (
      <div className="p-4 md:p-6 max-w-7xl mx-auto space-y-6" aria-busy>
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
          <Skeleton className="h-7 w-52" />
          <Skeleton className="h-5 w-24" />
        </div>
        <div className="bg-surface shadow-sm rounded-xl p-4 border space-y-4">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
            <Skeleton className="h-10 w-64" />
            <Skeleton className="h-6 w-16" />
            <Skeleton className="h-10 w-64" />
          </div>
          <Skeleton className="h-48" />
        </div>
        <Skeleton className="h-48" />
        <Skeleton className="h-72" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-4">
        <div className="max-w-xl rounded-lg border border-negative/40 p-4 bg-negative-soft text-negative-fg">
          <div className="font-semibold">Ocorreu um erro</div>
          <div className="text-sm mt-1">{error}</div>
          <div className="mt-3">
            <Button onClick={reloadStats}>Tentar novamente</Button>
          </div>
        </div>
      </div>
    );
  }

  if (!stats || orderedClubs.length === 0) {
    return <div className="p-4">Dados indisponíveis.</div>;
  }

  return (
    <div className="p-4 md:p-6 max-w-7xl mx-auto space-y-6">
      {/* Topo */}
      <div className="flex items-center gap-2 flex-wrap">
        <Link
          to="/"
          className="inline-flex items-center gap-1.5 rounded-lg border px-3 py-1.5 text-sm shadow-sm bg-surface hover:bg-surface-raised"
        >
          ← Voltar
        </Link>
        <span className="text-fg-subtle text-sm">Detalhes da Partida</span>
        <div className="flex-1" />
        <Link
          to={`/match/${matchId}/goals`}
          className="inline-flex items-center gap-1.5 rounded-lg border px-3 py-1.5 text-sm shadow-sm bg-surface hover:bg-surface-raised font-medium"
        >
          ⚽ Análise de Gols
        </Link>
      </div>

      {/* Painel Overall (toggle) */}
      <div className="bg-surface shadow-sm rounded-xl p-4 border">
        <div className="flex items-center justify-between gap-3 flex-wrap">
          <div className="flex items-center gap-3 flex-wrap">
            <h2 className="text-base font-semibold text-fg-secondary">Histórico dos clubes</h2>
            {orderedClubs.slice(0, 2).map((c) => (
              <div key={c.clubId} className="flex items-center gap-1.5">
                <Crest src={crestUrl(c.clubCrestAssetId)} alt={c.clubName} size={24} rounded="rounded-full" />
                <span className="text-sm text-fg-muted font-medium">{c.clubName}</span>
              </div>
            ))}
          </div>
          <Button onClick={() => setShowOverallPanel((v) => !v)}>
            {showOverallPanel ? "▲ Minimizar" : "▼ Ver histórico"}
          </Button>
        </div>

        {showOverallPanel && (
          <>
            {overallErr && (
              <div className="mt-3 text-sm text-negative-fg bg-negative-soft border border-negative/30 rounded p-2">{overallErr}</div>
            )}
            <div className="mt-3 grid grid-cols-1 md:grid-cols-2 gap-4">
              {orderedClubs.slice(0, 2).map((c) => (
                <OverallSummaryCard
                  key={c.clubId}
                  clubId={c.clubId}
                  clubName={c.clubName}
                  crestAssetId={c.clubCrestAssetId}
                  overall={overallCache.get(c.clubId)}
                  playoffs={playoffsCache.get(c.clubId)}
                />
              ))}
            </div>
            {overallBusy && <div className="mt-3 text-sm text-fg-muted">Carregando histórico do(s) clube(s)…</div>}
          </>
        )}
      </div>

      {/* Team Stats Section */}
      {haveTwoClubs && clubsWithGoalsConceded.length >= 2 && (
        <div className="bg-surface shadow-sm rounded-xl p-4 border">
          <h2 className="text-lg font-semibold mb-4">Estatísticas da Partida</h2>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            <div>
              <h3 className="text-base font-medium mb-2 flex items-center gap-2">
                <Crest
                  src={crestUrl(clubsWithGoalsConceded[0]?.clubCrestAssetId)}
                  alt={`Escudo ${clubsWithGoalsConceded[0]?.clubName ?? "Clube A"}`}
                  size={24}
                  rounded="rounded-full"
                />
                {clubsWithGoalsConceded[0]?.clubName ?? "Clube A"}
              </h3>
              <TeamStatsSection
                clubStats={clubsWithGoalsConceded[0]}
                loading={false}
                error={null}
                hiddenStats={["matches", "results"]}
              />
            </div>
            <div>
              <h3 className="text-base font-medium mb-2 flex items-center gap-2">
                <Crest
                  src={crestUrl(clubsWithGoalsConceded[1]?.clubCrestAssetId)}
                  alt={`Escudo ${clubsWithGoalsConceded[1]?.clubName ?? "Clube B"}`}
                  size={24}
                  rounded="rounded-full"
                />
                {clubsWithGoalsConceded[1]?.clubName ?? "Clube B"}
              </h3>
              <TeamStatsSection
                clubStats={clubsWithGoalsConceded[1]}
                loading={false}
                error={null}
                hiddenStats={["matches", "results"]}
              />
            </div>
          </div>
        </div>
      )}


      {/* Cabeçalho dos clubes + placar e highlights */}
      <div className={`bg-surface shadow-sm rounded-xl p-4 border ${heroBorderClass} ${heroBg}`}>
        {haveTwoClubs ? (
          <>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 items-center">
              {/* Esquerda */}
              <div className="flex items-center gap-3 px-2 py-1 justify-center sm:justify-start">
                <Crest
                  src={crestUrl(orderedClubs[0]?.clubCrestAssetId)}
                  alt={`Escudo ${orderedClubs[0]?.clubName ?? "Clube A"}`}
                  size={48}
                  rounded="rounded-full"
                />
                <div className="min-w-0">
                  <div className="font-semibold leading-tight truncate">
                    {orderedClubs[0]?.clubName ?? "Clube A"}
                  </div>
                  {leftIsSelected && (
                    <span className="text-[11px] text-accent font-medium">Clube selecionado</span>
                  )}
                </div>
              </div>

              {/* Placar */}
              <div className="flex items-center justify-center gap-3">
                {haveScore && (
                  <ResultPill outcome={leftWon ? "W" : rightWon ? "L" : "D"} variant="solid" />
                )}
                <span className={`font-display text-4xl sm:text-5xl font-bold tabular-nums leading-none ${leftWon ? "text-positive" : rightWon ? "text-negative" : "text-fg-secondary"}`}>
                  {goalsA}
                </span>
                <span className="text-fg-subtle text-xl font-light">–</span>
                <span className={`font-display text-4xl sm:text-5xl font-bold tabular-nums leading-none ${rightWon ? "text-positive" : leftWon ? "text-negative" : "text-fg-secondary"}`}>
                  {goalsB}
                </span>
                {haveScore && (
                  <ResultPill outcome={rightWon ? "W" : leftWon ? "L" : "D"} variant="solid" />
                )}
              </div>

              {/* Direita */}
              <div className="flex items-center gap-3 px-2 py-1 justify-center sm:justify-end">
                <div className="min-w-0 text-right">
                  <div className="font-semibold leading-tight truncate">
                    {orderedClubs[1]?.clubName ?? "Clube B"}
                  </div>
                  {rightIsSelected && (
                    <span className="text-[11px] text-accent font-medium">Clube selecionado</span>
                  )}
                </div>
                <Crest
                  src={crestUrl(orderedClubs[1]?.clubCrestAssetId)}
                  alt={`Escudo ${orderedClubs[1]?.clubName ?? "Clube B"}`}
                  size={48}
                  rounded="rounded-full"
                />
              </div>
            </div>

            {/* Tabela comparativa com heat */}
            <div className="overflow-x-auto mt-4">
              <table className="w-full table-fixed text-xs sm:text-sm border text-center">
                <thead>
                  <tr className="bg-surface-raised">
                    <th className="p-1.5 sm:p-2 w-1/3">{orderedClubs[0]?.clubName ?? "Clube A"}</th>
                    <th className="p-1.5 sm:p-2 w-1/3">Estatística</th>
                    <th className="p-1.5 sm:p-2 w-1/3">{orderedClubs[1]?.clubName ?? "Clube B"}</th>
                  </tr>
                </thead>
                <tbody>
                  {comparisonStats.map(({ label, key }) => {
                    const va = Number((orderedClubs[0] as any)?.[key] ?? 0);
                    const vb = Number((orderedClubs[1] as any)?.[key] ?? 0);
                    const heat = cellHeat(va, vb);
                    const total = va + vb || 1;
                    const barA = Math.round((va / total) * 100);
                    const barB = 100 - barA;
                    return (
                      <tr key={String(key)} className="border-t">
                        <td className={`p-2 tabular-nums ${heat.a}`}>
                          <div className="flex flex-col items-center gap-0.5">
                            <span>{fmt(va)}</span>
                            <div className="w-full h-1 rounded-full bg-surface-sunken overflow-hidden">
                              <div
                                className={`h-full ${va > vb ? "bg-positive" : va < vb ? "bg-negative" : "bg-border"}`}
                                style={{ width: `${barA}%` }}
                              />
                            </div>
                          </div>
                        </td>
                        <td className="p-2 font-medium text-fg-muted">{label}</td>
                        <td className={`p-2 tabular-nums ${heat.b}`}>
                          <div className="flex flex-col items-center gap-0.5">
                            <span>{fmt(vb)}</span>
                            <div className="w-full h-1 rounded-full bg-surface-sunken overflow-hidden">
                              <div
                                className={`h-full ${vb > va ? "bg-positive" : vb < va ? "bg-negative" : "bg-border"}`}
                                style={{ width: `${barB}%` }}
                              />
                            </div>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            {/* MVP */}
            {mom && (
              <div className="mt-4 flex items-center gap-2 flex-wrap">
                <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full border border-gold/40 bg-gold-soft text-gold-fg text-sm font-semibold">
                  🏆 {mom.playerName}
                </span>
                <span className="text-xs text-fg-muted">Man of the Match</span>
              </div>
            )}
          </>
        ) : (
          // Fallback quando só há 1 clube na resposta
          <div className="flex flex-col gap-3">
            <div className="flex items-center gap-2 px-2 py-1 rounded">
              <Crest
                src={crestUrl(orderedClubs[0]?.clubCrestAssetId)}
                alt={`Escudo ${orderedClubs[0]?.clubName ?? "Clube"}`}
                size={32}
                rounded="rounded-full"
              />
              <div className="font-semibold flex items-center gap-2">
                {orderedClubs[0]?.clubName ?? "Clube"}
                {leftIsSelected && (
                  <Badge className="bg-accent text-accent-fg border-accent">Clube selecionado</Badge>
                )}
              </div>
            </div>
            <div className="text-sm text-fg-muted">
              Sem dados do adversário para esta partida. Alguns painéis ficam indisponíveis.
            </div>
          </div>
        )}
      </div>

      {/* Eventos de jogo (match_event_aggregate) */}
      <MatchEaPostGameStats
        data={eventAggregates}
        loading={eventAggregatesLoading}
        error={eventAggregatesError}
      />

      {/* Player Stats Tables by Club */}
      {orderedClubs.map((clubRow) => {
        const clubPlayers = players.filter((p) => p.clubId === clubRow.clubId);
        const opponent = orderedClubs.find((c) => c.clubId !== clubRow.clubId);
        const clubWon = haveTwoClubs && !!opponent && clubRow.totalGoals > opponent.totalGoals;
        const clubLost = haveTwoClubs && !!opponent && clubRow.totalGoals < opponent.totalGoals;
        const clubBorderClass = clubWon
          ? "border-l-4 border-l-positive"
          : clubLost
          ? "border-l-4 border-l-negative"
          : "border-l-4 border-l-border-strong";

        return (
          <div key={clubRow.clubId} className={`bg-surface shadow-sm rounded-xl p-4 border ${clubBorderClass}`}>
            <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <Crest
                src={crestUrl(clubRow?.clubCrestAssetId)}
                alt={`Escudo ${clubRow?.clubName ?? "Clube"}`}
                size={24}
                rounded="rounded-full"
              />
              {clubRow?.clubName ?? "Clube"} - Jogadores
            </h3>

            <PlayerStatsTable
              // API rows carry a subset of PlayerStats; the table treats the extra fields as optional
              players={clubPlayers as PlayerStats[]}
              loading={false}
              error={null}
              clubStats={
                haveTwoClubs
                  ? (clubsWithGoalsConceded.find((c) => c.clubId === clubRow.clubId) as any) || null
                  : (orderedClubs.find((c) => c.clubId === clubRow.clubId) as any) || null
              }
              minMatches={0}
              searchTerm=""
              initialSortKey={sortKey}
              initialSortOrder={sortOrder}
              pageSize={50}
              showPagination={false}
              showSearch={false}
              showTitle={false}
              hiddenColumns={["matchesPlayed", "totalSecondsPlayed", "totalWins", "totalLosses", "totalDraws", "winPercent", "totalMom"]}
              onSortChange={(key, order) => {
                setSortKey(key);
                setSortOrder(order);
              }}
            />
          </div>
        );
      })}

      {/* Goal Linking Section - Only for selected club */}
      {selectedClubId && (
        <GoalLinkingSection
          matchId={matchId!}
          clubId={selectedClubId}
          clubName={orderedClubs.find((c) => c.clubId === selectedClubId)?.clubName ?? ""}
          clubCrestAssetId={orderedClubs.find((c) => c.clubId === selectedClubId)?.clubCrestAssetId}
          players={players.filter((p) => p.clubId === selectedClubId)}
        />
      )}
    </div>
  );
}
